// First node MUST verify the shared secret (jobs-mcp spec §6, v1-mandatory).
// The value lives in the LXC env (/etc/n8n/n8n.env), never in this JSON.
const req = $input.first().json;
const secret = $env.JOBS_WEBHOOK_SECRET;
const presented = (req.headers || {})['x-jobs-webhook-secret'];
if (!secret || presented !== secret) {
  return [{ json: { ok: false, error: { code: 'unauthorized', message: 'missing or invalid webhook secret' } } }];
}
const body = req.body || {};
// Executor-side validation uses its own code; E_* always means the gateway refused.
const fail = (message) => [{ json: { ok: false, error: { code: 'executor_schema', message } } }];
// The gateway scopes spend to (caller, X-Gateway-Job-Id) and pins the first cap
// it sees for that job (gateway spec §1, §5): both come from the dispatch body.
const jobId = body.job_id;
if (typeof jobId !== 'string' || !/^[A-Za-z0-9._-]{1,64}$/.test(jobId)) {
  return fail('job_id is missing or is not a valid gateway job id');
}
const cap = body.budget_cap_usd;
// 0.10 is the n8n-executor caller's per-request ceiling in the gateway registry:
// a larger cap would be refused 400 E_BUDGET_CAP_INVALID on every attempt.
if (typeof cap !== 'number' || !Number.isFinite(cap) || cap < 0 || cap > 0.10) {
  return fail('budget_cap_usd must be a number in [0, 0.10] for gateway-smoke (the n8n-executor per-request ceiling)');
}
// Defense in depth: jobs-mcp already validated payload against the registry
// schema; re-check so an authenticated-but-forged call cannot pick a pricier
// model or ship an oversized prompt.
const payload = body.payload || {};
const model = payload.model ?? 'haiku';
if (model !== 'haiku') return fail('payload.model must be haiku');
const prompt = payload.prompt ?? 'Reply with the single word: ok';
if (typeof prompt !== 'string' || prompt.length === 0) return fail('payload.prompt must be a non-empty string');
let bytes;
try {
  bytes = encodeURIComponent(prompt).replace(/%[0-9A-F]{2}/g, 'x').length;
} catch {
  return fail('payload.prompt is not valid text');
}
if (bytes > 2048) return fail('payload.prompt exceeds 2 KiB');
// Floored to whole micro-USD, fixed six decimals: never above the cap jobs-mcp
// stored, and byte-identical on every attempt so the gateway's job-cap pin
// cannot see a formatting difference. The 1e-6 absorbs binary float error
// (0.000003 * 1e6 = 2.9999999999999996).
const capHeader = (Math.floor(cap * 1e6 + 1e-6) / 1e6).toFixed(6);
return [{ json: {
  ok: true,
  job_id: jobId,
  attempt: body.attempt ?? null,
  cap_header: capHeader,
  chat: { model, max_tokens: 64, messages: [{ role: 'user', content: prompt }] },
} }];

// Read the ledger before calling (gateway spec §11). This executor never reports
// success without a completion it observed itself: /ledger/jobs counts rows
// charged at the reservation (timeout, aborted, swept) in spent_usd, so an
// earlier charge does not prove an earlier completion.
const built = $('Verify And Build').first().json;
const res = $input.first().json; // fullResponse: {data|body, headers, statusCode}
const raw = res.data ?? res.body;
let led = null;
try { led = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch {}
const fail = (code, message) => [{ json: { call: false, ok: false, error: { code, message: String(message).slice(0, 1000) } } }];
const errCode = led && led.error ? led.error.code : null;
// 404 E_NOT_FOUND "no ledger rows" = the gateway has never admitted a call for
// this (caller, job): the first call. Any other 404 is a misroute, not a first call.
if (res.statusCode === 404 && errCode === 'E_NOT_FOUND' && /no ledger rows/.test(led.error.message || '')) {
  return [{ json: { call: true, ...built } }];
}
if (res.statusCode !== 200 || !led || errCode) {
  return fail('gateway_ledger_error', `gateway /ledger/jobs returned ${res.statusCode}${errCode ? ' ' + errCode : ''}`);
}
if ((led.held_list_usd ?? 0) > 0) {
  return fail('gateway_call_in_flight',
    `an earlier attempt of job ${built.job_id} still holds a $${led.held_list_usd} gateway reservation; retry once it settles`);
}
if ((led.spent_usd ?? 0) > 0) {
  // No second spend, and no claim of a completion this attempt did not see.
  return fail('prior_attempt_charged',
    `job ${built.job_id} was already charged $${led.spent_usd} (list) across ${led.requests} gateway request(s); ` +
    `not calling again, and not reporting success without a completion — GET /ledger/jobs/${built.job_id}?caller=n8n-executor is the source of truth`);
}
// Rows exist but nothing was charged or held (every earlier call was released): safe to call.
return [{ json: { call: true, ...built } }];

// Turn the gateway reply into the jobs-mcp completion report (jobs spec §6;
// gateway spec §14 slice 3). No completion text is reported.
const res = $input.first().json; // fullResponse: {data|body, headers, statusCode}
const raw = res.data ?? res.body;
let body = null;
try { body = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch {}
const h = res.headers || {};
// jobs-mcp keeps error.message (cap 1024) but the terminal error.code is always
// retries_exhausted — so the message must carry the gateway's code and scope.
const fail = (code, message) => [{ json: { ok: false, error: { code: String(code).slice(0, 64), message: String(message).slice(0, 1000) } } }];
if (res.statusCode !== 200 || !body || !Array.isArray(body.choices)) {
  const e = (body && body.error) || {};
  const scope = e.scope ? ` scope=${e.scope}` : '';
  return fail(e.code || 'gateway_http_error', `gateway returned ${res.statusCode} ${e.code || ''}${scope}: ${e.message || 'unparseable response'}`);
}
const g = body.gateway || {};
const num = (v) => (v === undefined || v === null || v === '' ? null : Number(v));
const spent = num(g.job_spent_usd ?? h['x-gateway-job-spent-usd']);
if (spent === null || !Number.isFinite(spent)) {
  // The gateway always reports job spend when a job id is sent; without it the
  // report would be ok with spent_usd null, which the §11 proof must never see.
  return fail('gateway_bad_response', 'gateway answered 200 without the job spend (gateway.job_spent_usd)');
}
return [{ json: {
  ok: true,
  result: {
    request_id: g.request_id ?? h['x-gateway-request-id'] ?? null,
    model: body.model ?? null,
    usage: body.usage ?? null,
    billed_usd: num(g.billed_usd ?? h['x-gateway-billed-usd']),
    list_usd: num(g.list_usd ?? h['x-gateway-list-usd']),
    finish_reason: (body.choices[0] && body.choices[0].finish_reason) || null,
  },
  artifacts: [],
  // List-equivalent USD, cumulative over this job — the same unit as the job's
  // budget_cap (gateway SIGN-OFF 5), and what /ledger/jobs/{id} reports.
  spent_usd: spent,
} }];
